const schema::ClassSchema& pc_class() { return schema_named("AoCPlayerControllerBP_C"); }

const schema::RpcSchema& rpc_of(const char* name) {
    const schema::RpcSchema* r = pc_class().rpc(name);
    if (!r) {
        std::printf("  [FAIL] no RPC %s\n", name);
        std::exit(2);
    }
    return *r;
}

std::optional<ObjectState> load(const cf::Block& b, const char* cls) { return load_object_state_hex(schema_named(cls), b.hex, b.bits, b.rep); }

/// The RepLayout block a state writes from an empty shadow.
Bits rep_block_of(const ObjectState& o) {
    RepShadow shadow;
    BunchWriter w;
    bool failed = false;
    if (write_rep_block(*o.schema, o.state, shadow, w, {}, &failed) == 0 || failed) return Bits();
    return Bits(w);
}

std::optional<RpcCall> read_field(const cf::Block& b) {
    const Bits bits = bits_of_hex(b.hex, b.bits);
    return with_exact(bits, [&](const uint8_t* d, size_t, size_t n) -> std::optional<RpcCall> {
        size_t pos = 0;
        auto calls = read_rpc_fields(pc_class(), d, n, pos, {});
        if (!calls || pos != n || calls->size() != 1) return std::nullopt;
        return std::move((*calls)[0]);
    });
}

const Value* param(const RpcCall& c, const char* path) {
    const schema::RepCommand* cmd = c.rpc ? rpc_command(*c.rpc, path) : nullptr;
    if (!cmd) return nullptr;
    const auto it = c.params.values.find(cmd->handle);
    return it == c.params.values.end() ? nullptr : &it->second;
}

/// The name as UE prints it ("InstancedFoliageActor_25600_-41_19_0": the text and the number the wire carries); empty for no name or None.
std::string name_of(const Value* v) {
    const NameValue* n = v ? v->get_if<NameValue>() : nullptr;
    return n ? fname_text(*n) : std::string();
}

Bits written_field(const RpcCall& c) {
    BunchWriter w;
    bool failed = false;
    write_rpc_field(pc_class(), *c.rpc, c.params, w, {}, &failed);
    return failed ? Bits() : Bits(w);
}

void test_fname() {
    std::printf("FName: the text and the instance number the wire carries\n");
    const NameValue cell = fname_parse("InstancedFoliageActor_25600_-41_19_0");
    CHECK(cell.text == "InstancedFoliageActor_25600_-41_19" && cell.number == 1 && fname_text(cell) == "InstancedFoliageActor_25600_-41_19_0", "a trailing _0 is the number 1");
    const NameValue fismc = fname_parse("IntrepidGatherableFISMC_12");
    CHECK(fismc.text == "IntrepidGatherableFISMC" && fismc.number == 13, "a trailing _12 is the number 13");
    const NameValue bare = fname_parse("IntrepidGatherableFISMC");
    CHECK(bare.text == "IntrepidGatherableFISMC" && bare.number == 0 && fname_text(bare) == "IntrepidGatherableFISMC", "a name with no suffix has the number 0");
    CHECK(fname_parse("Tree_Oak_007").number == 0 && fname_parse("Tree_Oak_007").text == "Tree_Oak_007", "a suffix with a leading zero is part of the text (UE's ParseNumber)");
    CHECK(fname_parse("Tree_").number == 0 && fname_parse("_5").number == 0 && fname_parse("a_1234567890").number == 0, "an empty suffix, an empty text and ten digits are not split");
    CHECK(fname_text(NameValue::hardcoded_name(0)).empty(), "a hardcoded name (None) has no text");
    // every name of the thirteen starts, as the capture's FName and as a parse of its printed form, writes the same bits
    size_t same = 0;
    for (const cf::Start& s : cf::kStarts) {
        const auto call = read_field(s.field);
        const Value* owner = call ? param(*call, "FoliageName") : nullptr;
        const NameValue* n = owner ? owner->get_if<NameValue>() : nullptr;
        same += n && fname_parse(s.owner) == *n ? 1 : 0;
    }
    CHECK(same == sizeof(cf::kStarts) / sizeof(cf::kStarts[0]), "parsing the printed owner of each captured start gives the captured FName");
}

void test_starts() {
    std::printf("ServerStartInteractionWithFoliage: the client's thirteen starts\n");
    size_t read = 0, typed = 0, back = 0, no_index_when_zero = 0;
    for (const cf::Start& s : cf::kStarts) {
        const auto call = read_field(s.field);
        if (!call || !call->rpc || std::string(call->rpc->name) != "ServerStartInteractionWithFoliage" || !call->decoded) continue;
        ++read;
        const Value* index = param(*call, "OriginalInstanceIndex");
        const Value* state = param(*call, "FoliageState");
        const bool names = name_of(param(*call, "FoliageName")) == s.owner && name_of(param(*call, "FoliageComponentUUID")) == s.component;
        const bool idx_ok = s.has_instance ? (index && index->get_if<int64_t>() && static_cast<uint32_t>(*index->get_if<int64_t>()) == s.instance) : (index == nullptr);
        const bool st_ok = state && state->get_if<uint64_t>() && *state->get_if<uint64_t>() == s.state;
        if (names && idx_ok && st_ok) ++typed;
        if (written_field(*call) == bits_of_hex(s.field.hex, s.field.bits)) ++back;
        no_index_when_zero += (!s.has_instance && s.instance == 0) || s.has_instance ? 1 : 0;
    }
    const size_t n = sizeof(cf::kStarts) / sizeof(cf::kStarts[0]);
    CHECK(n == 13, "thirteen starts in the captures");
    CHECK(read == n, "all thirteen read to their last bit as the PlayerController's RPC");
    CHECK(typed == n, "each names the instance (omitted when 0), the owner, the component and a state of 1 or 2");
    CHECK(back == n, "and is written back to the exact bits of the capture");
    CHECK(no_index_when_zero == n, "(an instance index of 0 is not sent)");
    // 1428: the Oak at index 0: no index parameter, state Adult; 1451: a Daffodil, index 9, Juvenile
    for (const cf::Start& s : cf::kStarts) {
        if (s.capture == 1428) CHECK(!s.has_instance && std::string(s.owner) == "InstancedFoliageActor_25600_-41_19_0" && std::string(s.component) == "IntrepidGatherableFISMC_0" && s.state == 2, "1428: the Oak at (-41, 19) FISMC_0, index 0 (left out), Adult");
        if (s.capture == 1451) CHECK(s.has_instance && s.instance == 9 && s.state == 1 && std::string(s.component) == "IntrepidGatherableFISMC_16", "1451: a Daffodil, FISMC_16 index 9, Juvenile");
    }
}

void test_foliage_data() {
    std::printf("UPlayerInfo.FoliageData: the set and clear blocks of the harvests\n");
    size_t read = 0, back = 0, sets = 0, clears = 0, typed = 0;
    for (const cf::FoliageData& f : cf::kFoliageData) {
        const auto o = load(f.block, "UPlayerInfo");
        if (!o) continue;
        ++read;
        if (rep_block_of(*o) == bits_of_hex(f.block.hex, f.block.bits)) ++back;
        const auto get = [&](const char* path) { return o->state.get(*o->schema, path); };
        const Value* dur = get("FoliageData.Duration");
        const Value* start = get("FoliageData.ServerStartTime");
        const Value* idx = get("FoliageData.OriginalInstanceIndex");
        const Value* st = get("FoliageData.FoliageState");
        const Value* tool = get("FoliageData.ToolRecordId");
        const bool set = f.duration > 0.0f;
        (set ? sets : clears) += 1;
        const bool ok = dur && dur->get_if<float>() && *dur->get_if<float>() == f.duration && start && start->get_if<double>() && *start->get_if<double>() == f.start_time && idx &&
                        idx->get_if<int64_t>() && static_cast<uint32_t>(*idx->get_if<int64_t>()) == f.instance && st && st->get_if<uint64_t>() && *st->get_if<uint64_t>() == f.state && tool &&
                        tool->get_if<int64_t>() && static_cast<uint64_t>(*tool->get_if<int64_t>()) == f.tool_record && name_of(get("FoliageData.FoliageName")) == f.owner &&
                        name_of(get("FoliageData.FoliageComponentUUID")) == f.component;
        if (ok) ++typed;
    }
    const size_t n = sizeof(cf::kFoliageData) / sizeof(cf::kFoliageData[0]);
    CHECK(n == 30, "thirty FoliageData blocks in the captures (sixteen sets and fourteen clears: three harvests of 1429 and 1451 are cut at the capture's start or end)");
    CHECK(read == n, "all read to their last bit as the pawn's UPlayerInfo");
    CHECK(back == n, "and are written back to the exact bits (the RepLayout block of the one property)");
    CHECK(typed == n, "each is typed: the duration, the start on the synchronized clock, the instance, the owner and component, the state, the tool's record");
    CHECK(sets + clears == n && sets > 0 && clears > 0, "sets and clears both occur");
    size_t clears_ok = 0;
    for (const cf::FoliageData& f : cf::kFoliageData) {
        if (f.duration > 0.0f) continue;
        if (f.instance == 0xFFFFFFFFu && f.state == 3 && f.start_time == 0.0 && std::string(f.owner).empty() && std::string(f.component).empty() && f.tool_record == 0 && f.block.bits == 438) ++clears_ok;
    }
    CHECK(clears_ok == clears, "a clear is 438 bits: duration 0, start 0, index 0xFFFFFFFF, no names, state 3 (Empty), no tool");
}
