void test_rpcs() {
    std::printf("the server's foliage RPCs\n");
    size_t confirms = 0, confirm_ok = 0, interrupts = 0, interrupt_ok = 0, callouts = 0;
    for (const cf::Rpc& r : cf::kRpcs) {
        const std::string name = r.name;
        if (name == "ClientConfirmMultiInteractFoliage") {
            ++confirms;
            // the field loop entry: the field header then the parameter (InteractIndex, left at 0: a clear send bit)
            confirm_ok += r.bits == 1 ? 1 : 0;
        } else if (name == "ClientInterruptInteractionWithFoliage") {
            ++interrupts;
        } else if (name == "CalloutQueueReplication") {
            ++callouts;
        }
    }
    CHECK(confirms == 12 && confirm_ok == confirms, "twelve ClientConfirmMultiInteractFoliage calls, each a one-bit parameter (the default InteractIndex)");
    CHECK(interrupts == 1 && callouts == 5, "one ClientInterruptInteractionWithFoliage (capture 1464) and five callouts in the foliage frames (1464 has two: the refusal and its removal)");
    // the interrupt as a typed call: the parameters (OriginalInstanceIndex, FoliageName, FoliageComponentUUID) of 1464's refused start
    const schema::RpcSchema& rpc = rpc_of("ClientInterruptInteractionWithFoliage");
    for (const cf::Rpc& r : cf::kRpcs) {
        if (std::string(r.name) != "ClientInterruptInteractionWithFoliage") continue;
        const Bits bits = bits_of_hex(r.hex, r.bits);
        const auto call = with_exact(bits, [&](const uint8_t* d, size_t, size_t n) -> std::optional<RpcCall> {
            size_t pos = 0;
            auto p = read_rpc_params(rpc, d, n, pos, {});
            if (!p || pos != n) return std::nullopt;
            RpcCall c;
            c.rpc = &rpc;
            c.params = std::move(*p);
            c.decoded = true;
            return c;
        });
        const Value* index = call ? param(*call, "OriginalInstanceIndex") : nullptr;
        interrupt_ok += call && index && index->get_if<int64_t>() && *index->get_if<int64_t>() == 47 && name_of(param(*call, "FoliageName")) == "IFA_NodeLayoutReplicator_108646108518008_4_0" &&
                                name_of(param(*call, "FoliageComponentUUID")) == "IntrepidGatherableFISMC_11"
                            ? 1
                            : 0;
        BunchWriter w;
        bool failed = false;
        write_rpc_params(rpc, call ? call->params : RpcParams{}, w, {}, &failed);
        CHECK(!failed && Bits(w) == bits, "the interrupt is written back to the exact bits (701 bits: the index, the owner's name, the component's)");
    }
    CHECK(interrupt_ok == 1, "1464's interrupt names the instance of its refused start: index 47, the owner IFA and FISMC_11");
    // 1464's callout is the one capture_mount.h holds: type 4, the table "Economy", the key GatheringInterruption_Movement
    bool found = false;
    for (const capture_mount::Callout& c : capture_mount::kCallouts) {
        if (c.capture == 1464 && c.packet == 191) found = std::string(c.table) == "Economy" && std::string(c.key) == "GatheringInterruption_Movement" && c.callout_type == 4 && c.point_size == 32;
    }
    CHECK(found, "1464's callout (packet 191) is type 4, point size 32, Economy / GatheringInterruption_Movement");
}

/// A component block as the state would write it from a shadow at the capture's base key with the capture's deleted ElementIDs.
Bits component_block_of(const ObjectState& o, const cf::Component& c) {
    BunchWriter w;
    bool failed = false;
    if (c.block.rep) {
        RepShadow shadow;
        if (write_rep_block(*o.schema, o.state, shadow, w, {}, &failed) == 0 || failed) return Bits();
    }
    if (c.has_states) {
        const auto layout = fast_array_layout(*o.schema, "IndexedStates");
        if (!layout) return Bits();
        FastArrayShadows shadows;
        FastArrayShadow sh;
        sh.array_key = c.base_key;
        for (uint32_t i = 0; i < c.deleted_count; ++i) sh.items.push_back({static_cast<int32_t>(c.deleted[i]), 0});
        shadows.by_field[layout->field] = sh;
        write_fast_array_fields(*o.schema, o.arrays, shadows, w, {}, &failed);
        if (failed) return Bits();
    }
    return Bits(w);
}

bool item_is(const FastArrayItem& it, uint32_t id, uint32_t key, uint32_t state) {
    if (it.id != static_cast<int32_t>(id)) return false;
    const auto k = it.values.values.find(2);
    const auto s = it.values.values.find(1);
    return k != it.values.values.end() && s != it.values.values.end() && k->second.get_if<uint64_t>() && *k->second.get_if<uint64_t>() == key && s->second.get_if<uint64_t>() &&
           *s->second.get_if<uint64_t>() == state;
}

/// True when the loaded component's array holds the changed items of the capture (the deleted ones are the base shadow's, not the state's).
bool component_items_match(const ObjectState& o, const cf::Component& c) {
    const FastArrayState* a = o.arrays.find(fast_array_layout(*o.schema, "IndexedStates")->field);
    if (!a) return c.changed_count == 0;
    if (a->items().size() != c.changed_count || a->array_key() != c.array_key) return false;
    for (uint32_t i = 0; i < c.changed_count; ++i) {
        if (!item_is(a->items()[i], c.changed[i].id, c.changed[i].key, c.changed[i].state)) return false;
    }
    return true;
}
// CoA : C-Y-B

void test_indexed_states() {
    std::printf("UIntrepidFoliageStateComponent: every captured IndexedStates block\n");
    const schema::ClassSchema& comp = schema_named("UIntrepidFoliageStateComponent");
    CHECK(fast_array_layout(comp, "IndexedStates").has_value(), "IndexedStates is a fast array the codec knows (Items.Value.States, Items.Key)");
    CHECK(comp.command("FoliageComponentUUID") && comp.command("bInitialized"), "the component replicates FoliageComponentUUID and bInitialized");
    size_t read = 0, items_ok = 0, back = 0, with_deletes = 0, total_items = 0;
    for (size_t i = 0; i < cf::kStateCount; ++i) {
        const cf::Component& c = cf::kStates[i];
        const auto o = load(c.block, "UIntrepidFoliageStateComponent");
        if (!o) continue;
        ++read;
        if (component_items_match(*o, c)) ++items_ok;
        if (component_block_of(*o, c) == bits_of_hex(c.block.hex, c.block.bits)) ++back;
        with_deletes += c.deleted_count > 0 ? 1 : 0;
        total_items += c.changed_count;
    }
    CHECK(cf::kStateCount == 61, "61 distinct IndexedStates blocks");
    CHECK(read == cf::kStateCount, "all read to their last bit");
    CHECK(items_ok == cf::kStateCount, "each array holds the changed items of the capture, at the capture's array key");
    CHECK(back == cf::kStateCount, "and the writer reproduces the exact bits from the array and a shadow at the capture's base key with its deleted IDs");
    CHECK(with_deletes >= 5 && total_items >= 100, "some of them delete instances (back at their painted state) and between them carry over a hundred items");
    // the states the items carry: EFoliageState (0 Infancy, 1 Juvenile, 2 Adult, 3 Empty) in the live changes; the login's snapshot (capture 1198) lists the instances that are Empty as 11
    // (3 + 8: its 620 Empty items in 322 of the TSV's instances, plants, trees and stones alike, and none as 3), the growing ones as 0 and 1.  2 (Adult) is the painted default of a tree
    // and never sent.
    std::set<uint32_t> seen;
    size_t eleven = 0, threes = 0;
    for (size_t i = 0; i < cf::kStateCount; ++i) {
        for (uint32_t k = 0; k < cf::kStates[i].changed_count; ++k) {
            const uint32_t st = cf::kStates[i].changed[k].state;
            seen.insert(st);
            eleven += st == 11 ? 1 : 0;
            threes += st == 3 ? 1 : 0;
        }
    }
    CHECK(seen == std::set<uint32_t>({0, 1, 3, 11}), "the captured states are 0, 1, 3 and 11 (Adult, 2, is the painted default of a tree and never sent)");
    CHECK(eleven > 100 && threes > 0, "11 (Empty in a login snapshot) is the common value of the full lists, 3 (Empty, live) of the harvests' changes");
}

void test_opens() {
    std::printf("AIntrepidStateIFA: the twelve captured opens\n");
    size_t actors = 0, actors_back = 0, names_ok = 0, comps_ok = 0, comps_back = 0, comps_total = 0;
    for (const cf::IfaOpen& open : cf::kIfaOpens) {
        const auto a = load(open.actor, "AIntrepidStateIFA");
        if (!a) continue;
        ++actors;
        if (rep_block_of(*a) == bits_of_hex(open.actor.hex, open.actor.bits)) ++actors_back;
        const Value* name = a->state.get(*a->schema, "FoliageName");
        names_ok += name_of(name) == open.name ? 1 : 0;
        for (uint32_t i = 0; i < open.component_count; ++i) {
            const cf::Component& c = open.components[i];
            ++comps_total;
            const auto o = load(c.block, "UIntrepidFoliageStateComponent");
            if (!o) continue;
            const Value* uuid = o->state.get(*o->schema, "FoliageComponentUUID");
            const Value* init = o->state.get(*o->schema, "bInitialized");
            if (name_of(uuid) == c.uuid && init && init->get_if<bool>() && *init->get_if<bool>() == c.initialized && component_items_match(*o, c)) ++comps_ok;
            if (component_block_of(*o, c) == bits_of_hex(c.block.hex, c.block.bits)) ++comps_back;
        }
    }
    CHECK(actors == 12 && actors_back == 12, "the twelve actor blocks (1468's, 1463's, 1428's three and the seven cells of 1198's login) read to their last bit and are written back to the exact bits");
    CHECK(names_ok == 12, "each names its owner (FoliageName)");
    CHECK(comps_total == 28 + 28 + 20 + 20 + (7 + 22 + 10 + 19 + 12 + 10 + 22) + 8 && comps_ok == comps_total && comps_back == comps_total,
          "and their 206 component blocks read, hold the captured items and write back to the exact bits");
    size_t painted = 0, town = 0, centred = 0;
    for (const cf::IfaOpen& open : cf::kIfaOpens) {
        painted += open.actor.bits == 520 ? 1 : 0;
        town += open.actor.bits == 592 ? 1 : 0;
        // a painted cell stands at its centre: ((cx + 0.5) * 25600, (cy + 0.5) * 25600) for InstancedFoliageActor_25600_<cx>_<cy>_0
        int cx = 0, cy = 0, z = 0;
        if (std::sscanf(open.name, "InstancedFoliageActor_25600_%d_%d_%d", &cx, &cy, &z) == 3) {
            centred += open.location[0] == static_cast<int64_t>((cx + 0.5) * 25600.0) && open.location[1] == static_cast<int64_t>((cy + 0.5) * 25600.0) ? 1 : 0;
        }
    }
    CHECK(painted == 10 && town == 2, "the painted cells' actor blocks (1428's three, 1198's seven) are 520 bits, the town's runtime foliage (1463, 1468) 592: a longer name");
    CHECK(centred == 10, "a painted cell's actor stands at the cell's centre ((cx + 0.5) * 25600, (cy + 0.5) * 25600)");
    // SerializeNewActor's location (scale 10) and the block's ReplicatedMovement (a whole number of cm: an AActor's FRepMovement) are the same place: x and y x10 apart, z the header's tenths
    // rounded to the nearest cm with a tie going down (1198's cell -31_16: 12807.5 cm in the header, 12807 in the block)
    size_t same_place = 0;
    for (const cf::IfaOpen& open : cf::kIfaOpens) {
        if (std::string(open.name).rfind("InstancedFoliageActor_25600_", 0) != 0) continue;
        same_place += open.spawn_scaled && open.spawn[0] == open.location[0] * 10 && open.spawn[1] == open.location[1] * 10 && open.location[2] == (open.spawn[2] + 4) / 10 ? 1 : 0;
    }
    CHECK(same_place == 10, "the ten painted cells' open header and ReplicatedMovement name one place: x and y x10 apart, z the header's tenths rounded to the nearest cm, a tie down");
}
