void test_frame() {
    std::printf("capture 1463: the result frame's order\n");
    const size_t n = sizeof(cf::kFrame1463) / sizeof(cf::kFrame1463[0]);
    CHECK(n == 6, "six entries");
    if (n != 6) return;
    CHECK(std::string(cf::kFrame1463[0].what) == "PC ClientUpdateItemDurability" && std::string(cf::kFrame1463[1].what) == "PC ClientReceiveStorageEvent" &&
              std::string(cf::kFrame1463[2].what) == "PC ClientConfirmMultiInteractFoliage" && cf::kFrame1463[0].packet == cf::kFrame1463[2].packet,
          "the tool's wear, the storage event and the confirm share one packet, in that order");
    CHECK(std::string(cf::kFrame1463[3].what) == "PC XPTracker" && cf::kFrame1463[3].packet == cf::kFrame1463[0].packet + 1, "the XPTracker follows in the next packet");
    CHECK(std::string(cf::kFrame1463[4].what).find("IFA") == 0 && cf::kFrame1463[4].count == 20 && cf::kFrame1463[4].packet == cf::kFrame1463[3].packet + 1, "then the state actor's open (20 components)");
    CHECK(std::string(cf::kFrame1463[5].what) == "pawn FoliageData clear" && cf::kFrame1463[5].packet == cf::kFrame1463[4].packet + 1, "and the pawn's FoliageData is cleared last");
}

// ---- the client's call on a subobject it names by path, beside a retail start --------------------------------------------------------------------

/// The Oak's start of capture 1428 (packet 53): the actor block's two bits, the payload's bit count and the captured field make a content block of the PlayerController's channel.
const cf::Start& oak_start() {
    for (const cf::Start& s : cf::kStarts) {
        if (s.capture == 1428 && s.packet == 53) return s;
    }
    std::printf("  [FAIL] capture 1428's start is not in capture_foliage.h\n");
    std::exit(2);
}

BunchWriter actor_block_of(const BunchWriter& payload) {
    BunchWriter out;
    write_content_block(out, BlockHeader{}, payload, /*server_form=*/false);
    return out;
}

BunchWriter field_bits(const cf::Start& s) {
    const std::vector<uint8_t> bytes = bits_of_hex(s.field.hex, s.field.bits).bytes();
    BunchWriter payload;
    payload.write_bit_range(bytes.data(), 0, s.field.bits);
    return payload;
}

BunchWriter joined(std::initializer_list<const BunchWriter*> parts) {
    BunchWriter out;
    for (const BunchWriter* p : parts) out.write_bit_range(p->data(), 0, p->bit_pos());
    return out;
}

std::optional<ClientBunch> read_bunch(const Bits& bits) {
    return with_exact(bits, [&](const uint8_t* d, size_t, size_t n) { return read_client_bunch(pc_class(), nullptr, d, n); });
}

/// True when the call is the Oak's start as capture 1428's client sent it, decoded: the owner, the component, the state Adult, no instance index.
bool is_oak_start(const ClientRpc& r) {
    const cf::Start& s = oak_start();
    const Value* state = r.call.rpc ? param(r.call, "FoliageState") : nullptr;
    return r.on_actor && r.call.rpc && std::string(r.call.rpc->name) == "ServerStartInteractionWithFoliage" && r.call.decoded && name_of(param(r.call, "FoliageName")) == s.owner &&
           name_of(param(r.call, "FoliageComponentUUID")) == s.component && state && state->get_if<uint64_t>() && *state->get_if<uint64_t>() == s.state && !param(r.call, "OriginalInstanceIndex");
}
// C:Y:B x C.O.A

void test_in_place_blocks() {
    std::printf("the client's call on a subobject it names by path (the 550-bit bunch of the trees' retests), beside a retail start\n");
    namespace cip = capture_in_place;
    const BunchWriter call = cip::block();
    const Bits call_bits(call);
    CHECK(call_bits.size() == cip::kBlockBits, "the block is 550 bits, the size of the client's bunch");
    CHECK(call_bits.slice(0, cip::kLoggedBits) == bits_of_hex(cip::kLoggedHex, cip::kLoggedBits),
          "its first 192 bits are the 24 bytes worldd logged of the client's bunch: no RepLayout, a subobject, the default GUID, flags 5, the outer's first 54 bits");
    {
        size_t pos = 0;
        const auto v = with_exact(call_bits, [&](const uint8_t* d, size_t, size_t n) { return read_content_block(d, n, pos, /*server_form=*/false); });
        CHECK(v && !v->header.is_actor && !v->header.has_rep_layout && v->header.object.ObjectId == 0 && v->header.in_place && v->header.in_place->path == cip::kPath &&
                  v->header.in_place->flags == 5 && v->header.in_place->outer.ObjectId == cip::kOuterObjectId && v->payload_bits == 52 && pos == cip::kBlockBits,
              "the client's form of a block names the subobject in place: its path, flags 5 and the outer's GUID, a 52-bit payload, the block ends at bit 550");
        const auto back = with_exact(call_bits, [&](const uint8_t* d, size_t, size_t n) { return read_content_blocks(d, n, 0, /*server_form=*/false); });
        CHECK(back && back->size() == 1 && (*back)[0].header == cip::header(), "and the header reads back as it was written");
        // what the reader did with this block before (its first step, read_object, takes a GUID and refuses the default one, ObjectId 1: read_content_block then failed, and read_client_bunch
        // dropped the whole bunch -- the retests' "does not read: ignored")
        const auto old_step = with_exact(call_bits, [&](const uint8_t* d, size_t, size_t n) {
            wire::PacketReader r(d, (n + 7) / 8, n);
            r.set_pos(2);
            return read_object(r);
        });
        CHECK(!old_step, "(read_object, the old reader's first step, still refuses the block's object: the default GUID; the refusal now ends in the in-place name, not in the bunch)");
        size_t spos = 0;
        const auto server = with_exact(call_bits, [&](const uint8_t* d, size_t, size_t n) { return read_content_block(d, n, spos, /*server_form=*/true); });
        CHECK(!server && spos == 0, "the server's form still refuses ObjectId 1 (a block of the server's names its subobject by GUID)");
        BunchWriter refused;
        CHECK(write_content_block(refused, cip::header(), BunchWriter{}, /*server_form=*/true) == 0 && refused.bit_pos() == 0, "and the server's writer refuses a block named in place");
    }
    const cf::Start& oak = oak_start();
    const BunchWriter start = actor_block_of(field_bits(oak));
    // the call alone: read, nothing to answer, not a bunch that does not read
    {
        const auto r = read_bunch(call_bits);
        CHECK(r && r->rpcs.empty() && r->in_place_blocks == 1 && r->skipped_blocks == 1 && r->in_place.size() == 1 && r->in_place[0].name.path == cip::kPath && r->in_place[0].payload_bits == 52,
              "a bunch of the call alone reads: no RPC, one block named in place (its path and 52 payload bits kept), skipped");
    }
    // the start beside it, in both orders: the start is read whole
    {
        const BunchWriter before = joined({&call, &start});
        const auto r = read_bunch(Bits(before));
        CHECK(r && r->rpcs.size() == 1 && is_oak_start(r->rpcs[0]) && r->in_place_blocks == 1 && r->skipped_blocks == 1,
              "the call, then capture 1428's start: the start is read to its last bit (the Oak, Adult), the call skipped (this bunch was dropped whole before)");
        const BunchWriter after = joined({&start, &call});
        const auto q = read_bunch(Bits(after));
        CHECK(q && q->rpcs.size() == 1 && is_oak_start(q->rpcs[0]) && q->in_place_blocks == 1, "the start, then the call: the same");
    }
    // thirteen of them (a 7150-bit bunch, a size the logs of the retests had) and the start behind them
    {
        BunchWriter many;
        for (int i = 0; i < 13; ++i) many.write_bit_range(call.data(), 0, call.bit_pos());
        CHECK(many.bit_pos() == 7150, "thirteen calls are 7150 bits");
        const BunchWriter with_start = joined({&many, &start});
        const auto r = read_bunch(Bits(with_start));
        CHECK(r && r->rpcs.size() == 1 && is_oak_start(r->rpcs[0]) && r->in_place_blocks == 13 && r->in_place.size() == kMaxInPlaceKept && r->skipped_blocks == 13,
              "thirteen calls and the start behind them: the start is read, thirteen blocks counted, the first eight kept");
    }
    // a malformed name still fails the bunch: its extent is unknown
    {
        BunchWriter bad;
        bad.write_bit(0);
        bad.write_bit(0);
        emit::FIntrepidNetworkGUID root;
        root.ObjectId = 1;
        emit::write_intrepid_guid(bad, root);
        bad.write_uint8(4);   // the checksum flag with no path flag: UE writes a checksum with the path only
        bad.write_sip(0);
        CHECK(!read_bunch(Bits(bad)).has_value(), "a name with the checksum flag and no path flag does not read: the bunch is refused");
        CHECK(!read_bunch(call_bits.slice(0, 400)).has_value(), "a call cut in the middle (400 of its 550 bits) does not read");
        CHECK(!read_bunch(call_bits.slice(0, 300)).has_value(), "nor one cut inside its path (300 bits)");
        BunchWriter filler;
        for (int i = 0; i < 52; ++i) filler.write_bit(1);
        BunchWriter over;
        write_block_header(over, cip::header(), /*server_form=*/false);
        over.write_sip(1000);   // 1000 payload bits claimed, 52 present
        over.write_bit_range(filler.data(), 0, filler.bit_pos());
        CHECK(!read_bunch(Bits(over)).has_value(), "a call whose payload runs past the bunch does not read");
    }
    // the bound on the work: as many calls as an RPC bunch may hold read, one more does not
    {
        const auto calls = [&](size_t n) {
            BunchWriter b;
            for (size_t i = 0; i < n; ++i) b.write_bit_range(call.data(), 0, call.bit_pos());
            return b;
        };
        const auto r = read_bunch(Bits(calls(kMaxClientRpcsPerBunch)));
        CHECK(r && r->in_place_blocks == kMaxClientRpcsPerBunch, "a bunch of 1024 such calls reads");
        CHECK(!read_bunch(Bits(calls(kMaxClientRpcsPerBunch + 1))).has_value(), "one more is refused (the bound of the RPCs of a bunch)");
    }
    // an RPC field the class has no RPC for (an index beyond the class, a property): skipped by its bits, the start behind it read
    {
        const uint32_t beyond = pc_class().num_fields();
        BunchWriter loop;
        loop.write_serialize_int(beyond, pc_class().field_max());
        loop.write_sip(5);
        loop.write_bits(0x15, 5);
        loop.write_serialize_int(0, pc_class().field_max());   // field 0 is AuthServerIDReplicated, a property
        loop.write_sip(3);
        loop.write_bits(0x5, 3);
        const BunchWriter start_field = field_bits(oak);
        loop.write_bit_range(start_field.data(), 0, start_field.bit_pos());
        const BunchWriter block = actor_block_of(loop);
        const auto r = read_bunch(Bits(block));
        CHECK(r && r->rpcs.size() == 1 && is_oak_start(r->rpcs[0]) && r->skipped_fields.count == 2 && r->skipped_fields.first.size() == 2 && r->skipped_fields.first[0] == beyond &&
                  r->skipped_fields.first[1] == 0,
              "an index beyond the class and a property field are skipped (counted, their indices kept), the start behind them is read");
        size_t pos = 0;
        const Bits loop_bits(loop);
        const auto strict = with_exact(loop_bits, [&](const uint8_t* d, size_t, size_t n) { return read_rpc_fields(pc_class(), d, n, pos, {}); });
        CHECK(!strict && pos == 0, "read_rpc_fields without `skipped` (the server's direction, the captures' readers) still refuses them");
        BunchWriter header_only;   // a header that does not read: the extent is unknown, the bunch is refused
        header_only.write_serialize_int(beyond, pc_class().field_max());
        const BunchWriter bad_block = actor_block_of(header_only);
        CHECK(!read_bunch(Bits(bad_block)).has_value(), "a field header with no payload count does not read: the bunch is refused");
    }
}

